async function api(path,data){const response=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let body;try{body=await response.json()}catch{throw Error('No se pudo comunicar con el servidor.')}if(!response.ok){if(response.status===401){state.user=null;render()}throw Error(body.error||'No se pudo completar la operación.')}return body}
