 const mesas=sucursales.flatMap(s=>Array.from({length:s.sucursal_id===1?12:8},(_,i)=>({mesa_id:i+1,sucursal_id:s.sucursal_id,capacidad:i%3===0?6:i%2===0?2:4,estado:i%4===0?'Ocupada':'Disponible'})));
 const lotes=sucursales.flatMap(s=>ingredients.map((v,i)=>({lote_id:`S${s.sucursal_id}-L${String(i+1).padStart(3,'0')}`,ingrediente_id:i+1,sucursal_id:s.sucursal_id,fecha_ingreso:offsetDate(-5),fecha_vencimiento:offsetDate(i===1?3:20+i),cantidad_disponible:v[3]+(s.sucursal_id===2?3:0)})));
 const reservas=names.map((_,i)=>({reserva_id:i+1,cliente_id:i+1,sucursal_id:1,fecha_reserva:today(),hora_reserva:['10:00','11:30','13:00','14:30','19:00','15:00','16:30','18:00','19:30','20:00'][i],estado:i===2?'Pendiente':i===4?'Pendiente':'Confirmada',personas:i%3===0?4:2,duracion_min:90,observaciones:''}));
 const asignaciones=reservas.map((r,i)=>({reserva_id:r.reserva_id,mesa_id:[2,4,6,8,10,12,2,4,6,8][i],sucursal_id:1}));
 const visitas=[],ventas=[];
